#include <cmath>
#include <algorithm>
#include <cstring>
extern "C" void render(const double* P,int n,unsigned char* out,int N){
 const double S=227.1845065; std::memset(out,0,N*N);
 double rx=P[0],ry=P[1],th=atan2(P[4]-ry,P[3]-rx),w=0,d=0;
 for(int i=0;i<n;i++){
  double x=P[3*i],y=P[3*i+1],z=std::clamp(P[3*i+2],0.,15.);
  double W=z>0?std::max(0.,1.187*z-.3):0,D=z>0?1.38+1.075*z:0,O=z>0?std::max(0.,11.15-.0967*(z-10.91)*(z-10.91)):0;
  w=.02*w+.98*W;d=.02*d+.98*D;
  double dx=x-rx,dy=y-ry,L=hypot(dx,dy),o=std::min(O,L);
  if(L>(z>0?1.:.1))th=atan2(dy,dx);
  if(L>0){rx=x-dx*o/L;ry=y-dy*o/L;}
  if(w<.05)continue;
  double ex=cos(th),ey=sin(th),nx=-ey,ny=ex;
  double xa[4]={rx+w/2*nx,rx-w/2*nx,rx-d*ex+w/2*nx,rx-d*ex-w/2*nx};
  double ya[4]={ry+w/2*ny,ry-w/2*ny,ry-d*ey+w/2*ny,ry-d*ey-w/2*ny};
  int a=std::max(0,(int)(*std::min_element(xa,xa+4)/S*N)-1), b=std::min(N,(int)(*std::max_element(xa,xa+4)/S*N)+2);
  int c=std::max(0,(int)(*std::min_element(ya,ya+4)/S*N)-1), e=std::min(N,(int)(*std::max_element(ya,ya+4)/S*N)+2);
  for(int v=c;v<e;v++)for(int u=a;u<b;u++){
    double qx=(u+.5)*S/N-rx,qy=(v+.5)*S/N-ry,ss=-(qx*ex+qy*ey),tt=qx*nx+qy*ny;
    if(ss>=0&&ss<=d*(1-4*tt*tt/(w*w)))out[v*N+u]=1;
  }
 }
}
